    public static function dateFilter(string $module): ?string {
        return match ($module) {
            'appointments','availability' => 'starts_at',
            'recalls' => 'due_on',
            'clinical','comments','odontogram','documents','consents','budgets','payments','refunds','messages','responses' => 'created_at',
            default => null,
        };
    }
    public static function surveyQuestions(): string {
        return "¿Cómo evalúa la atención recibida?\n¿Cómo evalúa la claridad de las explicaciones del profesional?\n¿Cómo evalúa la puntualidad de su atención?\n¿Cómo evalúa la limpieza y comodidad de la clínica?";
    }
    public static function get(string $key): array { return self::all()[$key] ?? abort(404); }
    public static function keyFor(string $table): string { foreach(self::all() as $key=>$value) if($value['table']===$table) return $key; abort(404); }
    public static function teeth(): array { $teeth=[]; foreach([1,2,3,4,5,6,7,8] as $q) foreach(range(1,$q<5 ? 8 : 5) as $t) $teeth[]=$q*10+$t; return $teeth; }
    public static function permissions(): array {
        $p=['users.view','users.write','roles.view','roles.write','audit.view','reports.view','exports.view','comments.clinical','comments.administrative'];
        foreach(self::all() as $m) { $p[]=$m['permission'].'.view'; $p[]=$m['permission'].'.write'; }
        return array_values(array_unique($p));
    }
